//! Public-API differential conformance for triclinic periodic geometry.
//!
//! Expected closest images are generated by direct integer-lattice
//! enumeration, not by the production closest-vector bounds.

use nalgebra::{SMatrix, SVector};
use symtropy_math::{LatticeOffset, TriclinicPeriodicCell};

fn skew_cell() -> TriclinicPeriodicCell<2> {
    TriclinicPeriodicCell::new(
        SVector::from([3.0, -2.0]),
        SMatrix::<f64, 2, 2>::new(2.0, 1.8, 0.0, 0.5),
        [true, true],
    )
    .unwrap()
}

fn lcg_next(state: &mut u64) -> u64 {
    *state = state
        .wrapping_mul(6_364_136_223_846_793_005)
        .wrapping_add(1_442_695_040_888_963_407);
    *state
}

fn unit(state: &mut u64) -> f64 {
    (lcg_next(state) >> 11) as f64 / ((1_u64 << 53) as f64)
}

fn range(state: &mut u64, low: f64, high: f64) -> f64 {
    low + (high - low) * unit(state)
}

fn close(a: f64, b: f64, tolerance: f64) {
    assert!(
        (a - b).abs() <= tolerance,
        "expected {a:.16e} ~= {b:.16e} within {tolerance:.3e}"
    );
}

#[test]
fn fractional_rounding_is_not_the_skew_cell_nearest_image() {
    let cell = skew_cell();
    let displacement = *cell.basis() * SVector::from([0.49, 0.49]);
    let result = cell.minimum_image(&displacement, 128).unwrap();

    assert_eq!(result.image_offset, LatticeOffset::new([0, -1]));
    assert!(result.displacement.norm() < displacement.norm());
}

#[test]
fn public_closest_image_matches_independent_integer_enumeration() {
    let cell = skew_cell();
    let mut seed = 0x5055_424c_4943_4356_u64;

    for case in 0..1_000 {
        let fractional = SVector::from([
            range(&mut seed, -2.0, 2.0),
            range(&mut seed, -2.0, 2.0),
        ]);
        let displacement = *cell.basis() * fractional;
        let actual = cell
            .minimum_image(&displacement, 512)
            .unwrap_or_else(|error| panic!("case={case}: unexpected query error: {error}"));

        let mut oracle_score = f64::INFINITY;
        let mut oracle_offset = [0_i64; 2];
        for n0 in -12_i64..=12 {
            for n1 in -12_i64..=12 {
                let candidate = displacement
                    + *cell.basis() * SVector::from([n0 as f64, n1 as f64]);
                let score = candidate.norm_squared();
                if score < oracle_score
                    || (score == oracle_score && [n0, n1] < oracle_offset)
                {
                    oracle_score = score;
                    oracle_offset = [n0, n1];
                }
            }
        }

        close(actual.displacement.norm_squared(), oracle_score, 2e-11);
        assert_eq!(
            actual.image_offset.periods,
            oracle_offset,
            "integer image mismatch at deterministic case {case}"
        );
        assert!(
            actual.candidates_examined <= 512,
            "candidate budget exceeded without a typed error at case {case}"
        );
    }
}

#[test]
fn explicit_lattice_offsets_reconstruct_and_are_translation_invariant() {
    let cell = skew_cell();
    let point = *cell.origin() + *cell.basis() * SVector::from([0.25, 0.75]);
    let wrapped = cell.wrap_point(&point).unwrap();
    let reconstructed = cell
        .apply_offset(&wrapped.position, wrapped.image_offset)
        .unwrap();
    assert!((reconstructed - point).norm() < 1e-11);

    for shift in [
        LatticeOffset::new([1, 0]),
        LatticeOffset::new([-2, 3]),
        LatticeOffset::new([7, -5]),
    ] {
        let translated = cell.apply_offset(&point, shift).unwrap();
        let a = cell.minimum_image(&point, 128).unwrap();
        let b = cell.minimum_image(&translated, 128).unwrap();
        assert!((a.displacement - b.displacement).norm() < 1e-10);
    }
}
